{
  "iteration": 10,
  "pcvs": [
    {
      "name": "batch_changed",
      "expression": "int(self.batch_update_builder.batch_changed)",
      "rationale": "Separates fixed metadata reconstruction from unchanged-batch processing."
    },
    {
      "name": "tensor_preparation_paths",
      "expression": "int(self.batch_update_builder.batch_changed) * (int(not self.all_greedy) + int(not self.no_top_p) + int(not self.no_top_k) + 4 * int(not self.no_penalties) + int(not self.no_allowed_token_ids))",
      "rationale": "Counts sampling copies and, for penalties, three copies plus prompt-tensor construction."
    },
    {
      "name": "mask_transition_work",
      "expression": "int(len([ids for ids in self.req_output_token_ids if ids is not None and len(ids) <= 1]) > 0) + int(bool(self.batch_update_builder.added) and self.all_greedy)",
      "rationale": "Combines minimum-token transitions with the additional fixed work observed during all-greedy admission."
    },
    {
      "name": "request_preparation_work",
      "expression": "len(self.batch_update_builder.added) + 2 * int(bool(self.batch_update_builder.added)) + (self.num_reqs if self.batch_update_builder.batch_changed and not self.no_penalties else 0)",
      "rationale": "Represents admission setup, per-request initialization, and prompt-padding iterations."
    }
  ],
  "hypothesis": "Keeping metadata reconstruction, tensor preparation, mask transitions, and request-level work separate should preserve the main control-flow distinctions while accommodating the expensive initial admission without a dedicated feature."
}
